from pathlib import Path
from xml.sax.saxutils import escape
import subprocess
D=Path('/tmp/lending-build')
ink='#193d36'; teal='#28685c'; rust='#974322'; paper='#fbf7eb'; line='#a8b4a6'; gold='#e9b358'
def rect(x,y,w,h,c):return f'<rect x=\"{x}\" y=\"{y}\" width=\"{w}\" height=\"{h}\" fill=\"{c}\"/>'
def txt(x,y,s,n=17,f='Arial',c=ink,b='',a='start'):
 return f'<text x=\"{x}\" y=\"{y}\" text-anchor=\"{a}\" font-family=\"{f}\" font-size=\"{n}\" fill=\"{c}\" font-weight=\"{b or \"normal\"}\">{escape(s)}</text>'
def mono(x,y,s,c=teal):return txt(x,y,s,11,'Courier New',c,'bold')
def path(d,c=ink,w=2,fill='none'):return f'<path d=\"{d}\" stroke=\"{c}\" stroke-width=\"{w}\" fill=\"{fill}\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>'
def group(x,y,s):return f'<g transform=\"translate({x} {y})\">{s}</g>'
def drawing(k):
 if k==1:
  s=path('M8 47 L19 16 L78 10 L68 41 Z',ink,2,'#c3d3b9')+path('M14 49 L16 28 L72 23 L72 47 Z',ink,2,paper)+path('M10 49 L12 34 L68 29 L68 51 Z',ink,2,paper)+path('M6 46 L63 41 L80 33 L78 64 L64 74 L8 78 Z',ink,2,gold)+path('M63 41 L64 74 M23 55 L48 53 L48 62 L24 64 Z',ink,1.7)
 elif k==2:
  s=path('M9 20 L72 12 L82 20 L80 71 L17 78 L8 69 Z',ink,2,'#c3d3b9')+path('M17 28 L82 20 M17 28 L17 78 M9 20 L17 28 M24 35 L70 30 L70 50 L24 55 Z',ink,2)+path('M30 46 L64 42',ink,2)
  for x,y in [(33,44),(60,41)]:s+=f'<circle cx=\"{x}\" cy=\"{y}\" r=\"4\" stroke=\"{ink}\" stroke-width=\"2\" fill=\"{paper}\"/>'
  for i in range(6):s+=path(f'M{25+i*7} {60-i*.7} l4 -.4 v7 l-4 .4 z',ink,1.4,gold if i==0 else paper)
 else:
  s=path('M25 68 L42 10 Q43 4 49 6 L65 10 Q70 11 68 17 L52 72 M25 68 L53 74 L67 64',ink,3)+path('M34 24 L65 30 L56 62 L26 56 Z',ink,2,'#c3d3b9')+path('M34 24 L44 38 L62 37 M32 45 L57 51',ink,1.5)
  for x,y in [(27,66),(53,72)]:s+=f'<circle cx=\"{x}\" cy=\"{y}\" r=\"7\" fill=\"{ink}\"/><circle cx=\"{x}\" cy=\"{y}\" r=\"2\" fill=\"{paper}\"/>'
 return s
def base(title,right):
 return rect(0,0,540,336,paper)+rect(0,0,540,5,teal)+mono(20,29,title)+txt(520,29,right,11,'Courier New',teal,'bold','end')+path('M20 40 H520',line,1)
def obj(year,name,k,lines,q):
 s=base('LARCH STREET LIBRARY','LENDING COLLECTION')+txt(19,92,year,49,'Baskerville',rust)+txt(20,140,name,35,'Baskerville')+group(421,52,drawing(k))+path('M20 156 H520',line,1)
 for i,l in enumerate(lines):s+=txt(20,188+i*25,l,18)
 return s+rect(0,276,540,60,'#e1e9dc')+mono(20,296,'LOOK AGAIN')+txt(20,322,q,18,'Baskerville',ink,'bold')
intro=base('LARCH STREET LIBRARY','NEIGHBORHOOD LENDING COLLECTION')+txt(19,104,'Still in use',66,'Baskerville')+txt(21,142,'Three things worth passing on',25,'Baskerville',rust)
for i,k in enumerate([1,2,3]):intro+=group(21+i*105,153,drawing(k))
intro+=path('M20 248 H520',line,1)+txt(20,278,'A meal can outlast its cook. A birdcall can outlast',18)+txt(20,302,'the morning. A trolley can outlast a broken part.',18)+txt(20,326,'What travels with a thing when someone borrows it?',18)
box=obj('1978','Metal recipe box',1,['Inside are 46 handwritten cards. A borrower can','copy a recipe, put the card back, and make the','same meal in a different kitchen. Even the shape','of a letter can bring the cook to mind.'],'What would you copy besides the ingredients?')
tape=obj('1996','Cassette recorder',2,['This recorder belonged to a local bird club.','Imagine hearing a call you can’t quite name.','Wind the tape back and a friend can listen too,','even after the bird has flown.'],'How would you put a birdcall on paper?')
cart=obj('2011','Folding shopping trolley',3,['Its owner repaired it twice. Picture the first trip','after each fix. The owner already knew how to','fold it and how hard to pull on the way home.','A new borrower gets to learn those things too.'],'What would you ask the owner to show you?')
sign=base('LARCH STREET LIBRARY','VISITOR CARDS')+txt(20,99,'Pass on a memory',46,'Baskerville')+txt(20,144,'Think of something you have used again,',22,'Baskerville')+txt(20,172,'fixed, or shared.',22,'Baskerville')
for i,l in enumerate(['Take a card. Draw or write what happened.','Leave it in the pocket for the next visitor to read,','or take it home. Leave names off shared cards.']):sign+=txt(20,215+i*26,l,18)
sign+=rect(0,294,540,42,'#e1e9dc')+mono(20,320,'NO PENCIL?  TELL SOMEONE YOUR OBJECT’S STORY.')
pocket=base('LARCH STREET LIBRARY','SHARED CARDS')+txt(20,110,'The return pocket',48,'Baskerville')+txt(20,160,'Leave a memory here.',25,'Baskerville',rust)+txt(20,220,'Pick a card to read.',20)+txt(20,249,'Slip it back for the next visitor.',20)+path('M20 285 H520',line,1)+mono(20,312,'OPEN AT THE TOP')
def marks(x,y,w,h):
 return ''.join(path(f'M{a+dx*3} {b} h{dx*5} M{a} {b+dy*3} v{dy*5}',line,.65) for a,dx in ((x,-1),(x+w,1)) for b,dy in ((y,-1),(y+h,1)))
def page(name,s):
 svg=D/(name+'.svg');svg.write_text('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"8.5in\" height=\"11in\" viewBox=\"0 0 612 792\">'+s+'</svg>')
 subprocess.run(['rsvg-convert','-f','pdf','-o',str(D/(name+'.pdf')),str(svg)],check=True)
for i,pair in enumerate([(intro,box),(tape,cart),(sign,pocket)]):
 page(str(i),''.join(group(36,y,v)+marks(36,y,540,336) for y,v in zip([42,414],pair)))
subprocess.run(['pdfunite',*[str(D/(str(i)+'.pdf')) for i in range(3)],'Case and station panels.pdf'],check=True)
def slip():
 s=rect(0,0,258,336,'#fffdf7')+rect(0,0,258,5,teal)+mono(13,27,'LARCH STREET LIBRARY')+path('M13 38 H245',line,1)+txt(13,74,'Memory card',32,'Baskerville')+txt(13,108,'My object',17,'Baskerville',rust)+path('M13 135 H245',line,1)+txt(13,166,'I remember the time…',19,'Baskerville')+txt(13,191,'Draw or write here.',14)
 return s+path('M13 296 H245',line,1)+txt(13,317,'Share without a name, or keep it.',13)
page('slips',''.join(group(x,y,slip())+marks(x,y,258,336) for x in (36,318) for y in (42,414)))
Path('Visitor memory cards.pdf').write_bytes((D/'slips.pdf').read_bytes())
